#!/usr/bin/env node
/**
 * Worktree isolation entry point. Node stdlib only.
 *
 * Two callers:
 *   1. Claude Code SessionStart hook → `apply.mjs --quiet` (emits hook JSON).
 *   2. worktree-isolation skill → `apply.mjs --verbose --force` or `--status`.
 *
 * Reads the project's docker-compose*.yml files, generates per-worktree override
 * files (sibling .worktree.yml) with deterministic randomized host ports + suffixed
 * container_names, writes .env.worktree, and registers the generated files in the
 * per-worktree git exclude list.
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const PORT_RANGE_START = 20000;
export const PORT_RANGE_SIZE = 10000; // → 20000-29999
const GENERATED_BY = "# Auto-generated by ~/.claude/scripts/worktree-isolation/apply.mjs";

// ---------------------------------------------------------------------------
// Minimal YAML reader for compose files.
// shortcut: block maps/sequences, flow sequences of scalars, quotes and comments only;
// anchors, aliases, merge keys and flow maps come back as plain strings. Enough for
// `services.*.ports` and `container_name`; a real parser if a compose file needs more.

function stripComment(line) {
  let quote = null;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quote) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === "#" && (i === 0 || /\s/.test(line[i - 1]))) {
      return line.slice(0, i);
    }
  }
  return line;
}

function scalar(raw) {
  let s = raw.trim().replace(/^(?:&\S+|!\S*)\s*/, "").replace(/^(?:&\S+|!\S*)\s*/, "");
  if (s.startsWith("[") && s.endsWith("]")) {
    const inner = s.slice(1, -1).trim();
    return inner ? inner.split(",").map((x) => scalar(x)) : [];
  }
  if (s.length >= 2 && s[0] === '"' && s.endsWith('"')) return s.slice(1, -1).replace(/\\"/g, '"');
  if (s.length >= 2 && s[0] === "'" && s.endsWith("'")) return s.slice(1, -1).replace(/''/g, "'");
  if (/^-?\d+$/.test(s)) return Number(s);
  if (s === "" || s === "~" || s === "null") return null;
  return s;
}

/** Split `key: value` at the first `: ` (or trailing `:`) outside quotes; null if not a key. */
function splitKey(text) {
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quote) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === ":" && (i === text.length - 1 || text[i + 1] === " ")) {
      return [scalar(text.slice(0, i)), text.slice(i + 1).trim()];
    }
  }
  return null;
}

export function parseYaml(source) {
  const lines = [];
  for (const raw of source.replace(/\r\n?/g, "\n").split("\n")) {
    const text = stripComment(raw).replace(/\s+$/, "");
    if (!text.trim() || /^(---|\.\.\.)/.test(text)) continue;
    lines.push({ indent: text.length - text.trimStart().length, text: text.trim() });
  }
  let i = 0;

  function skipDeeper(indent) {
    while (i < lines.length && lines[i].indent > indent) i++;
  }

  function value(rest, indent) {
    if (/^[|>]/.test(rest.replace(/^(?:&\S+|!\S*)\s*/, ""))) {
      skipDeeper(indent);
      return "";
    }
    if (rest.replace(/^(?:&\S+|!\S*)\s*/, "") !== "") return scalar(rest);
    if (i < lines.length && lines[i].indent > indent) return block(lines[i].indent);
    // `key:` followed by `- item` at the key's own column is a sequence too.
    if (i < lines.length && lines[i].indent === indent && lines[i].text.startsWith("-")) return seq(indent);
    return null;
  }

  function map(indent, first) {
    const out = {};
    let entry = first;
    for (;;) {
      const kv = splitKey(entry);
      if (kv) out[kv[0]] = value(kv[1], indent);
      if (i >= lines.length || lines[i].indent !== indent || lines[i].text.startsWith("- ") || lines[i].text === "-") break;
      entry = lines[i++].text;
    }
    return out;
  }

  function seq(indent) {
    const out = [];
    while (i < lines.length && lines[i].indent === indent && (lines[i].text === "-" || lines[i].text.startsWith("- "))) {
      const text = lines[i++].text;
      const rest = text.slice(1).trim();
      if (!rest) out.push(i < lines.length && lines[i].indent > indent ? block(lines[i].indent) : null);
      else if (splitKey(rest) && !/^["'[]/.test(rest)) out.push(map(indent + text.length - rest.length, rest));
      else out.push(scalar(rest));
    }
    return out;
  }

  function block(indent) {
    if (lines[i].text === "-" || lines[i].text.startsWith("- ")) return seq(indent);
    return map(indent, lines[i++].text);
  }

  return lines.length ? block(lines[0].indent) : null;
}

// ---------------------------------------------------------------------------
// Ports

export function worktreeId(cwd) {
  return crypto.createHash("sha256").update(cwd).digest("hex").slice(0, 8);
}

export function allocatePort(worktree, service, originalHost, container) {
  const h = crypto.createHash("sha256").update(`${worktree}:${service}:${originalHost}:${container}`).digest();
  return PORT_RANGE_START + (h.readUInt32BE(0) % PORT_RANGE_SIZE);
}

/** Split a short-form port string on ':' while respecting ${...}. */
export function splitPortSpec(s) {
  const parts = [];
  let buf = "";
  let depth = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === "$" && s[i + 1] === "{") {
      depth++;
      buf += "${";
      i++;
    } else if (c === "}" && depth > 0) {
      depth--;
      buf += c;
    } else if (c === ":" && depth === 0) {
      parts.push(buf);
      buf = "";
    } else {
      buf += c;
    }
  }
  parts.push(buf);
  return parts;
}

/** [defaultPort, varName] for a host-port token: "54399" or "${PORT:-54399}". */
function hostPortToken(token) {
  const m = /^\$\{(\w+)(?::-([^}]*))?\}$/.exec(token);
  if (m) return [m[2] && /^\d+$/.test(m[2]) ? Number(m[2]) : null, m[1]];
  return /^\d+$/.test(token) ? [Number(token), null] : [null, null];
}

/** [start, count] for "3000-3005", [port, 1] for "3000", null otherwise. */
function portRange(token) {
  const m = /^(\d+)-(\d+)$/.exec(token);
  if (m && Number(m[2]) >= Number(m[1])) return [Number(m[1]), Number(m[2]) - Number(m[1]) + 1];
  return /^\d+$/.test(token) ? [Number(token), 1] : null;
}

/** One `ports:` entry as a mapping with newHostPort 0, or null when it cannot be read. */
export function parsePortEntry(entry, service) {
  if (entry && typeof entry === "object") {
    const container = Number(entry.target);
    let host = container;
    let varName = null;
    if (typeof entry.published === "number") host = entry.published;
    else if (entry.published != null) {
      const [def, v] = hostPortToken(String(entry.published));
      varName = v;
      host = def ?? container;
    }
    return { service, hostIp: entry.host_ip ?? null, originalHostPort: host, newHostPort: 0,
      containerPort: container, protocol: entry.protocol ?? "tcp", varName, count: 1 };
  }

  let s = String(entry).trim();
  let protocol = "tcp";
  const slash = s.lastIndexOf("/");
  if (slash !== -1) {
    protocol = s.slice(slash + 1);
    s = s.slice(0, slash);
  }
  const parts = splitPortSpec(s);
  let hostIp = null;
  let host;
  let container;
  let varName = null;
  let count = 1;
  if (parts.length === 3) hostIp = parts.shift();
  if (parts.length === 1) {
    // Bare port: Docker treats it as the container port; we still bind a deterministic host port.
    [container, count] = portRange(parts[0]) ?? [0, 1];
    host = container;
  } else if (parts.length === 2) {
    const range = portRange(parts[1]);
    if (!range) return null;
    [container, count] = range;
    if (count > 1) {
      // A range keeps its length: 3000-3005:3000-3005 moves as one block of six.
      const hostRange = portRange(parts[0]);
      if (!hostRange || hostRange[1] !== count) return null;
      host = hostRange[0];
    } else {
      [host, varName] = hostPortToken(parts[0]);
      host ??= container;
    }
  } else {
    return null;
  }
  return { service, hostIp, originalHostPort: host, newHostPort: 0, containerPort: container, protocol, varName, count };
}

// ---------------------------------------------------------------------------
// Compose files

export function findComposeFiles(cwd) {
  return fs
    .readdirSync(cwd)
    .filter((n) => /^(docker-)?compose.*\.ya?ml$/.test(n) && !/\.worktree\.ya?ml$/.test(n))
    .map((n) => path.join(cwd, n))
    .sort();
}

const services = (file) => parseYaml(fs.readFileSync(file, "utf-8"))?.services ?? {};

export function collectPortMappings(file, worktree) {
  const out = [];
  for (const [service, def] of Object.entries(services(file))) {
    for (const entry of def?.ports ?? []) {
      const pm = parsePortEntry(entry, service);
      if (!pm || pm.originalHostPort == null) continue;
      pm.newHostPort = allocatePort(worktree, service, pm.originalHostPort, pm.containerPort);
      out.push(pm);
    }
  }
  return out;
}

export function collectContainerNames(file) {
  const out = {};
  for (const [service, def] of Object.entries(services(file))) {
    if (typeof def?.container_name === "string" && def.container_name) out[service] = def.container_name;
  }
  return out;
}

const key = (k) => (/^[\w.-]+$/.test(k) ? k : JSON.stringify(k));

/**
 * The override file. Top-level `name:` sets COMPOSE_PROJECT_NAME for this stack; per
 * service, ports carry `!override` so Compose 2.24+ replaces the base list instead of
 * appending to it, and container_name gets the worktree suffix.
 */
export function renderOverrideYaml(mappings, containerNames, projectName, worktree) {
  const byService = new Map();
  for (const m of mappings) byService.set(m.service, [...(byService.get(m.service) ?? []), m]);
  const lines = [GENERATED_BY, "# DO NOT COMMIT. Regenerate with the worktree-isolation skill.",
    `name: ${JSON.stringify(projectName)}`, "services:"];
  for (const service of new Set([...byService.keys(), ...Object.keys(containerNames)])) {
    lines.push(`  ${key(service)}:`);
    if (byService.has(service)) {
      lines.push("    ports: !override");
      for (const m of byService.get(service)) {
        const span = (start) => (m.count > 1 ? `${start}-${start + m.count - 1}` : `${start}`);
        let spec = `${span(m.newHostPort)}:${span(m.containerPort)}`;
        if (m.hostIp) spec = `${m.hostIp}:${spec}`;
        if (m.protocol !== "tcp") spec += `/${m.protocol}`;
        lines.push(`      - ${JSON.stringify(spec)}`);
      }
    }
    if (service in containerNames) lines.push(`    container_name: ${JSON.stringify(`${containerNames[service]}-${worktree}`)}`);
  }
  return lines.join("\n") + "\n";
}

/** <SERVICE>_<CONTAINER_PORT>_HOST_PORT, e.g. POSTGRES_INTEGRATION_5432_HOST_PORT. */
export function envVarName(m) {
  const safe = m.service.replace(/[^A-Za-z0-9]+/g, "_").replace(/^_+|_+$/g, "").toUpperCase();
  return `${safe}_${m.containerPort}_HOST_PORT`;
}

/** chain: [[basePath, overridePath|null]] in order. */
export function renderEnvWorktree(projectName, worktree, chain, mappings) {
  const lines = [GENERATED_BY, "# DO NOT COMMIT. Source before running docker compose:",
    "#   set -a; source .env.worktree; set +a", `WORKTREE_ID=${worktree}`, `COMPOSE_PROJECT_NAME=${projectName}`];
  const files = chain.flatMap(([base, override]) => [path.basename(base), ...(override ? [path.basename(override)] : [])]);
  // Compose splits COMPOSE_FILE on ';' on Windows unless told otherwise.
  if (files.length) lines.push("COMPOSE_PATH_SEPARATOR=:", `COMPOSE_FILE=${files.join(":")}`);
  const seen = new Set();
  for (const m of mappings) {
    const v = envVarName(m);
    if (!seen.has(v)) lines.push(`${v}=${m.newHostPort}`), seen.add(v);
    // A compose that used ${VAR:-default} also gets VAR, so substitution picks up the new port.
    if (m.varName && !seen.has(m.varName)) lines.push(`${m.varName}=${m.newHostPort}`), seen.add(m.varName);
  }
  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------------------
// Git exclude

/** The per-checkout git dir (where info/exclude lives); follows a worktree's `.git` file. */
export function findGitDir(cwd) {
  const git = path.join(cwd, ".git");
  try {
    const st = fs.statSync(git);
    if (st.isDirectory()) return git;
    const content = fs.readFileSync(git, "utf-8").trim();
    if (content.startsWith("gitdir:")) {
      const target = path.resolve(cwd, content.slice(7).trim());
      return fs.existsSync(target) ? target : null;
    }
  } catch {}
  for (let dir = path.dirname(cwd); ; dir = path.dirname(dir)) {
    const candidate = path.join(dir, ".git");
    try {
      if (fs.statSync(candidate).isDirectory()) return candidate;
    } catch {}
    if (path.dirname(dir) === dir) return null;
  }
}

export function ensureGitExclude(cwd, patterns) {
  const gitDir = findGitDir(cwd);
  if (!gitDir) return false;
  const file = path.join(gitDir, "info", "exclude");
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const text = fs.existsSync(file) ? fs.readFileSync(file, "utf-8") : "";
  const existing = new Set(text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean));
  const toAdd = patterns.filter((p) => !existing.has(p));
  if (!toAdd.length) return false;
  const sep = text && !text.endsWith("\n") ? "\n" : "";
  fs.appendFileSync(file, `${sep}# Worktree isolation (auto-added)\n${toAdd.map((p) => `${p}\n`).join("")}`);
  return true;
}

export function overridePathFor(base) {
  const ext = path.extname(base);
  return path.join(path.dirname(base), `${path.basename(base, ext)}.worktree${ext}`);
}

function upToDate(base, override, envFile) {
  if (!fs.existsSync(override) || !fs.existsSync(envFile)) return false;
  const b = fs.statSync(base).mtimeMs;
  return fs.statSync(override).mtimeMs >= b && fs.statSync(envFile).mtimeMs >= b;
}

// ---------------------------------------------------------------------------
// Entry point

function summary(projectName, worktree, mappings) {
  const sorted = [...mappings].sort((a, b) => a.service.localeCompare(b.service) || a.containerPort - b.containerPort);
  const legacy = [...new Set(mappings.map((m) => String(m.originalHostPort)))].sort();
  return [
    `Worktree isolation active: project='${projectName}' (id=${worktree}).`,
    "",
    "Port mappings (legacy → worktree host):",
    ...sorted.map((m) => `  ${m.service}  container :${m.containerPort}  →  host ${m.newHostPort}  (was ${m.originalHostPort})`),
    "",
    "To bring up the stack from this worktree:",
    "  set -a; source .env.worktree; set +a",
    "  docker compose up -d",
    "(COMPOSE_FILE in .env.worktree auto-chains base + override files.)",
    "",
    "When running ad-hoc commands (e.g. test commands in CLAUDE.md) that hardcode",
    `legacy host ports like ${legacy.join(", ")}, substitute the matching new host port from the table above before executing.`,
  ].join("\n");
}

/** opts: { cwd, quiet, verbose, force, status }. Returns the exit code; output goes to log/err. */
export function run(opts, log = console.log, err = console.error) {
  const cwd = fs.realpathSync.native(path.resolve(opts.cwd ?? process.cwd()));
  const envFile = path.join(cwd, ".env.worktree");

  if (opts.status) {
    if (!fs.existsSync(envFile)) {
      err(`No .env.worktree at ${cwd}. Run with --force to generate.`);
      return 1;
    }
    log(fs.readFileSync(envFile, "utf-8"));
    return 0;
  }

  const nothing = (why) => {
    if (opts.quiet) log(JSON.stringify({ continue: true }));
    else if (opts.verbose) log(`${why} in ${cwd}. Nothing to isolate.`);
    return 0;
  };

  const composeFiles = findComposeFiles(cwd);
  if (!composeFiles.length) return nothing("No docker-compose files");

  const wid = worktreeId(cwd);
  const projectName = `${path.basename(cwd)}-${wid}`;
  const chain = [];
  const all = [];
  let regenerated = false;

  for (const base of composeFiles) {
    const mappings = collectPortMappings(base, wid);
    const names = collectContainerNames(base);
    if (!mappings.length && !Object.keys(names).length) continue;
    const override = overridePathFor(base);
    chain.push([base, override]);
    all.push(...mappings);
    if (!opts.force && upToDate(base, override, envFile)) continue;
    fs.writeFileSync(override, renderOverrideYaml(mappings, names, projectName, wid));
    regenerated = true;
  }

  if (!chain.length) return nothing("No services with ports or container_name");

  // Always write the env file when there is a chain: covers fresh dirs even if overrides exist.
  const env = renderEnvWorktree(projectName, wid, chain, all);
  if (!fs.existsSync(envFile) || fs.readFileSync(envFile, "utf-8") !== env) {
    fs.writeFileSync(envFile, env);
    regenerated = true;
  }

  ensureGitExclude(cwd, [".env.worktree", "*.worktree.yml", "*.worktree.yaml"]);

  const text = summary(projectName, wid, all);
  if (opts.quiet) {
    log(JSON.stringify({ hookSpecificOutput: { hookEventName: "SessionStart", additionalContext: text } }));
  } else {
    log(text);
    if (!regenerated) log("\n(no changes — overrides already up to date)");
  }
  return 0;
}

function parseArgs(argv) {
  const opts = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--cwd") opts.cwd = argv[++i];
    else if (a.startsWith("--cwd=")) opts.cwd = a.slice(6);
    else if (["--quiet", "--verbose", "--force", "--status"].includes(a)) opts[a.slice(2)] = true;
    else if (a === "-h" || a === "--help") opts.help = true;
    else throw new Error(`unknown argument: ${a}`);
  }
  return opts;
}

if (process.argv[1] && path.basename(process.argv[1]) === path.basename(fileURLToPath(import.meta.url))) {
  const argv = process.argv.slice(2);
  const quiet = argv.includes("--quiet");
  try {
    const opts = parseArgs(argv);
    if (opts.help) {
      console.log("usage: apply.mjs [--cwd DIR] [--quiet | --verbose] [--force] [--status]");
      process.exit(0);
    }
    process.exitCode = run(opts);
  } catch (e) {
    if (!quiet) throw e;
    // Never break the session: a minimal valid hook response, the error on stderr.
    console.log(JSON.stringify({ continue: true }));
    console.error(`worktree-isolation error: ${e.message}`);
  }
}
